class Solution {
  private int[] digits;
  private long[][][][][][] memo;

  private static boolean isGood(int x) {
    if (x < 10) return true;
    String s = Integer.toString(x);
    boolean inc = true, dec = true;
    for (int i = 1; i < s.length(); i++) {
      if (s.charAt(i) <= s.charAt(i - 1)) inc = false;
      if (s.charAt(i) >= s.charAt(i - 1)) dec = false;
    }
    return inc || dec;
  }

  // state: 0 single digit, 1 increasing, 2 decreasing, 3 broken
  private long dfs(int pos, int sum, int last, int state, boolean tight, boolean started) {
    if (pos == digits.length) return started && (state != 3 || isGood(sum)) ? 1 : 0;
    int s = started ? 1 : 0;
    if (!tight && memo[pos][sum][last][state][s] != null) return memo[pos][sum][last][state][s][0];
    int limit = tight ? digits[pos] : 9;
    long res = 0;
    for (int d = 0; d <= limit; d++) {
      boolean nt = tight && d == limit;
      if (!started && d == 0) {
        res += dfs(pos + 1, 0, 0, 0, nt, false);
        continue;
      }
      int ns;
      if (!started) ns = 0;
      else if (state == 3) ns = 3;
      else if (state == 0) ns = d > last ? 1 : d < last ? 2 : 3;
      else if (state == 1) ns = d > last ? 1 : 3;
      else ns = d < last ? 2 : 3;
      res += dfs(pos + 1, sum + d, d, ns, nt, true);
    }
    if (!tight) memo[pos][sum][last][state][s] = new long[] {res};
    return res;
  }

  private long count(long n) {
    if (n <= 0) return 0;
    String str = Long.toString(n);
    digits = new int[str.length()];
    for (int i = 0; i < digits.length; i++) digits[i] = str.charAt(i) - '0';
    memo = new long[digits.length][9 * digits.length + 10][10][4][2][];
    return dfs(0, 0, 0, 0, true, false);
  }

  public long countFancy(long l, long r) {
    return count(r) - count(l - 1);
  }
}
